import{_ as a,o as n,c as p,a2 as t}from"./chunks/framework.C4u7U0Dw.js";const d=JSON.parse('{"title":"销售与客户跟进提示词模板","description":"销售岗位的 5 条提示词模板：客户背调、分层报价、跟进节奏、异议处理、丢单复盘。","frontmatter":{"title":"销售与客户跟进提示词模板","description":"销售岗位的 5 条提示词模板：客户背调、分层报价、跟进节奏、异议处理、丢单复盘。"},"headers":[],"relativePath":"community/prompts/销售与客户跟进.md","filePath":"community/prompts/销售与客户跟进.md"}'),e={name:"community/prompts/销售与客户跟进.md"};function l(o,s,i,c,r,u){return n(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="📞-销售与客户跟进-·-5-条提示词模板" tabindex="-1">📞 销售与客户跟进 · 5 条提示词模板 <a class="header-anchor" href="#📞-销售与客户跟进-·-5-条提示词模板" aria-label="Permalink to &quot;📞 销售与客户跟进 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>销售的活，一半在说，一半在<strong>记</strong>。 记不住的客户 = 跟丢的客户。这几条都是帮你&quot;把脑子里的东西变成纸上的东西&quot;。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我卖的是【什么 / 卖给谁 / 什么价位】，客户是【情况】。</span></span>
<span class="line"><span>帮我产出【作战地图 / 报价 / 跟进话术】，形式【…】。</span></span>
<span class="line"><span>只基于我给的信息，不许替我猜客户的真实想法；不确定的标出来。</span></span></code></pre></div><hr><h2 id="_1-·-客户背调-→-一页作战地图" tabindex="-1">1 · 客户背调 → 一页作战地图 <a class="header-anchor" href="#_1-·-客户背调-→-一页作战地图" aria-label="Permalink to &quot;1 · 客户背调 → 一页作战地图&quot;">​</a></h2><p><strong>什么时候用</strong>：明天要见客户，你手上有点信息，但都是散的：微信聊过、官网看过、别人提过一句。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户基本信息：</span></span>
<span class="line"><span>- 公司 / 个人：【…】，规模和业务：【…】</span></span>
<span class="line"><span>- 我已知的公开信息（我查到的，注明来源）：【…】</span></span>
<span class="line"><span>- 之前接触记录：【什么时候聊过、聊了什么、对方说过什么关键句】</span></span>
<span class="line"><span>- 我的产品能对上他什么需求：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我出一页&quot;作战地图&quot;：</span></span>
<span class="line"><span>① 客户画像：他现在最可能的处境（基于我给的信息，标注这是推断）</span></span>
<span class="line"><span>② 他可能的三类痛点，按&quot;我能不能解决&quot;排序</span></span>
<span class="line"><span>③ 我要在会上问的 5 个问题（按&quot;从浅到深&quot;排，第一个问题必须极好回答）</span></span>
<span class="line"><span>④ 我手里可以给的三个&quot;价值锚点&quot;（案例、数据、资源）</span></span>
<span class="line"><span>⑤ 最坏情况：他为什么可能不买，我该怎么接</span></span>
<span class="line"><span>⑥ 我需要补查的信息清单</span></span>
<span class="line"><span>规矩：不许编客户的公司数据、不许编行业趋势；推断必须标&quot;这是推断&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：一页纸，见客户前 5 分钟能看完。</p><hr><h2 id="_2-·-报价方案-给三档-别只给一个数" tabindex="-1">2 · 报价方案（给三档，别只给一个数） <a class="header-anchor" href="#_2-·-报价方案-给三档-别只给一个数" aria-label="Permalink to &quot;2 · 报价方案（给三档，别只给一个数）&quot;">​</a></h2><p><strong>什么时候用</strong>：客户问&quot;多少钱&quot;，你报一个数，对方就开始砍。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的服务 / 产品：【说清交付什么】</span></span>
<span class="line"><span>成本与底价：【…（你自己填）】，我期望成交价：【…】</span></span>
<span class="line"><span>客户情况：【预算敏感度 / 他更在意价格还是效果 / 有没有对比的竞品】</span></span>
<span class="line"><span>交付周期与我的产能：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我设计三档报价（低 / 中 / 高），每一档写清：</span></span>
<span class="line"><span>① 包含什么（条目式，方便对比）</span></span>
<span class="line"><span>② 不包含什么（写清楚，防后期扯皮）</span></span>
<span class="line"><span>③ 这一档的定位一句话（例如&quot;尝鲜版&quot;&quot;性价比最优&quot;&quot;省心全包&quot;）</span></span>
<span class="line"><span>④ 客户问&quot;能不能便宜点&quot;时我的三种应对（不降价的换法 / 有条件降价 / 加量不加价）</span></span>
<span class="line"><span>最后给我一段&quot;报价说明&quot;的话术（300 字，说清为什么这个价，不贬低同行）。</span></span>
<span class="line"><span>规矩：所有数字只能来自我给的；不许编成功案例。</span></span></code></pre></div><p><strong>它给你</strong>：三档报价表 + 砍价应对 + 报价说明。<strong>&quot;不包含什么&quot;那一栏能省你很多事。</strong></p><hr><h2 id="_3-·-跟进节奏-隔多久、说什么、跟几次就停" tabindex="-1">3 · 跟进节奏（隔多久、说什么、跟几次就停） <a class="header-anchor" href="#_3-·-跟进节奏-隔多久、说什么、跟几次就停" aria-label="Permalink to &quot;3 · 跟进节奏（隔多久、说什么、跟几次就停）&quot;">​</a></h2><p><strong>什么时候用</strong>：客户说&quot;我再看看&quot;，你不知道该隔几天问一次，问多了怕烦，问少了怕忘。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户情况：【在什么行业 / 上次聊到哪一步 / 他明确说过什么 / 多久没联系了】</span></span>
<span class="line"><span>我这次想达成的目标：【不是&quot;成交&quot;，具体一点，例如&quot;让他确认预算范围&quot;】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 给我一个跟进节奏表（第几天 / 用什么渠道 / 目的是什么 / 说什么类型的内容）</span></span>
<span class="line"><span>② 每一步都写一条可以直接发的消息草稿（不许是&quot;最近考虑得怎么样&quot;这种废话，每次都要带信息增量）</span></span>
<span class="line"><span>③ 告诉我&quot;跟几次就该停&quot;，以及停掉之后还有什么不打扰的长期方式</span></span>
<span class="line"><span>④ 如果我这次真的要推一下，怎么推才不像在催</span></span>
<span class="line"><span>规矩：不编优惠、不编活动截止时间；我不能提供的信息不要出现在草稿里。</span></span></code></pre></div><p><strong>它给你</strong>：一张跟进节奏表 + 每条可直接发的草稿。</p><hr><h2 id="_4-·-异议处理-价格贵-再想想-我已经有供应商了" tabindex="-1">4 · 异议处理（价格贵 / 再想想 / 我已经有供应商了） <a class="header-anchor" href="#_4-·-异议处理-价格贵-再想想-我已经有供应商了" aria-label="Permalink to &quot;4 · 异议处理（价格贵 / 再想想 / 我已经有供应商了）&quot;">​</a></h2><p><strong>什么时候用</strong>：客户甩出一句标准拒绝，你的回答开始重复上一句。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户的原话：【原样写下来】</span></span>
<span class="line"><span>背后的情况：【他真正可能在担心什么，我知道多少写多少】</span></span>
<span class="line"><span>我的产品在这个点上：【真实情况，有短板也写】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按这三个常见异议分别给我应对：</span></span>
<span class="line"><span>① &quot;太贵了&quot; ② &quot;我再想想&quot; ③ &quot;我已经有供应商 / 合作方了&quot;</span></span>
<span class="line"><span>每个异议给我：</span></span>
<span class="line"><span>- 一句&quot;先接住&quot;的话（不反驳、不解释）</span></span>
<span class="line"><span>- 一个问句（把拒绝变成信息）</span></span>
<span class="line"><span>- 一段&quot;只讲一个点&quot;的回应（不堆优势）</span></span>
<span class="line"><span>另外给我：哪些情况应该直接放弃这单，别耗。</span></span>
<span class="line"><span>规矩：不贬低竞品、不编数据、不承诺公司政策之外的东西。</span></span></code></pre></div><p><strong>它给你</strong>：三类异议的完整应对 + 放弃标准。<strong>&quot;先接住再问&quot;是这行的基本功。</strong></p><hr><h2 id="_5-·-丢单复盘-这单为什么没成" tabindex="-1">5 · 丢单复盘（这单为什么没成） <a class="header-anchor" href="#_5-·-丢单复盘-这单为什么没成" aria-label="Permalink to &quot;5 · 丢单复盘（这单为什么没成）&quot;">​</a></h2><p><strong>什么时候用</strong>：单子丢了，你心里有个大概原因，但说不清到底哪一步错了。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这单的情况：</span></span>
<span class="line"><span>- 客户与需求：【…】</span></span>
<span class="line"><span>- 接触过程（按时间）：【第一次聊了什么 → 发过什么方案 → 对方反应 → 最后一次沟通】</span></span>
<span class="line"><span>- 丢单时的原话：【原样写】</span></span>
<span class="line"><span>- 我的判断：【我觉得是因为 XX】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我复盘：</span></span>
<span class="line"><span>① 按时间线标出&quot;三个可能的转折点&quot;（哪一步关系开始变冷）</span></span>
<span class="line"><span>② 每个转折点写出&quot;当时还有别的做法吗&quot;，各给 2 个具体替代动作</span></span>
<span class="line"><span>③ 区分：这是&quot;我的问题&quot;&quot;产品的问题&quot;还是&quot;客户本来就不合适&quot;</span></span>
<span class="line"><span>④ 给出一条可复用的改进（下次遇到同类客户，第二通电话就该做什么）</span></span>
<span class="line"><span>⑤ 这个客户还有没有回头的空间，如果有，第一步做什么</span></span>
<span class="line"><span>规矩：不许安慰我，也不用替我找借口；分析只能基于我给的过程记录。</span></span></code></pre></div><p><strong>它给你</strong>：一份能改行为的复盘。<strong>别让它安慰你</strong>——安慰的话在这没用。</p><hr><h2 id="⚠️-这条红线要记住" tabindex="-1">⚠️ 这条红线要记住 <a class="header-anchor" href="#⚠️-这条红线要记住" aria-label="Permalink to &quot;⚠️ 这条红线要记住&quot;">​</a></h2><p><strong>客户信息不能随便贴给 AI</strong>：手机号、微信聊天记录（含对方姓名公司）、报价底价、合同条款。 处理办法：<strong>换代号 + 去掉联系方式 + 底价用区间表示</strong>。 给 AI 的是&quot;结构&quot;，不是&quot;原件&quot;。</p><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/人力资源与招聘.html">人力资源与招聘</a></strong></p>`,34)])])}const q=a(e,[["render",l]]);export{d as __pageData,q as default};
